from pathlib import Path
import re

path = Path('/home/ubuntu/atelier-wordpress/atelier/bbpress/content-single-topic.php')
text = path.read_text()

new_actions = '''<div class="atelier-thread__actions" role="group" aria-label="Actions de la discussion"><a class="atelier-button atelier-button--reply" href="#new-reply"><svg aria-hidden="true" viewBox="0 0 24 24" focusable="false"><path d="M5 5.5h14a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2h-8l-4.5 3v-3H5a2 2 0 0 1-2-2v-8a2 2 0 0 1 2-2Z" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg><span>Répondre</span></a><?php if ( class_exists( 'PFC_Community' ) ) : $following = is_user_logged_in() && PFC_Community::is_following( get_current_user_id(), $topic_id ); ?><button type="button" class="atelier-button atelier-button--follow" data-pfc-follow data-topic-id="<?php echo esc_attr( $topic_id ); ?>" data-login="<?php echo esc_url( wp_login_url( $topic_url ) ); ?>" aria-pressed="<?php echo $following ? 'true' : 'false'; ?>"><svg aria-hidden="true" viewBox="0 0 24 24" focusable="false"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg><span data-follow-label><?php echo $following ? 'Vous suivez' : 'Suivre'; ?></span></button><?php endif; ?><button type="button" class="atelier-button atelier-button--share" data-atelier-share data-url="<?php echo esc_url( $topic_url ); ?>" data-label="Partager"><svg aria-hidden="true" viewBox="0 0 24 24" focusable="false"><circle cx="18" cy="5" r="2.2" fill="none" stroke="currentColor" stroke-width="1.7"/><circle cx="6" cy="12" r="2.2" fill="none" stroke="currentColor" stroke-width="1.7"/><circle cx="18" cy="19" r="2.2" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="m8 11 7.8-4.5M8 13l7.8 4.5" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg><span data-share-label>Partager</span></button><button type="button" class="atelier-button atelier-button--save" data-atelier-save data-save-key="atelier-topic-<?php echo esc_attr( $topic_id ); ?>" aria-pressed="false"><svg aria-hidden="true" viewBox="0 0 24 24" focusable="false"><path d="M6 4.5h12v15l-6-3.8-6 3.8v-15Z" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg><span data-save-label>Enregistrer</span></button></div>'''
text, count = re.subn(r'<div class="atelier-thread__actions".*?</div>', new_actions, text, count=1, flags=re.S)
assert count == 1, 'actions block not found'

new_footer = '''<footer class="atelier-post-footer"><span class="atelier-topic-upvotes" aria-label="Votes utiles du sujet"><svg aria-hidden="true" viewBox="0 0 24 24" focusable="false"><path d="M7 10v10H4V10h3Zm3 10h6.5a2 2 0 0 0 1.94-1.52l1.35-5.4A2 2 0 0 0 17.85 10H14l.6-3.1A2.4 2.4 0 0 0 12.25 4L10 10v10Z" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg><strong><?php echo esc_html( $vote_count ); ?></strong> upvotes</span><span class="atelier-source-note"><svg aria-hidden="true" viewBox="0 0 24 24" focusable="false"><path d="M6 3.5h9l3 3V20.5H6zM15 3.5v4h4M9 12h6M9 15h6" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/></svg><span>Source stable</span><button type="button" data-atelier-share data-url="<?php echo esc_url( $topic_url ); ?>" data-label="<?php echo esc_attr( wp_parse_url( $topic_url, PHP_URL_PATH ) ?: 'Copier le lien' ); ?>"><span data-share-label><?php echo esc_html( wp_parse_url( $topic_url, PHP_URL_PATH ) ?: 'Copier le lien' ); ?></span></button></span></footer>'''
