text = text.replace(old_footer, new_footer, 1)

new_reading = '''<section class="atelier-reading-card" id="machine-reading"><header><span>✧ Lecture claire</span><small>LLM-FIRST</small></header><h2>Ce sujet expose ce qui compte.</h2><p>Ce panneau explique comment le sujet est découpé pour une lecture humaine et pour les moteurs de recherche : source canonique, message initial, auteurs, dates et réponses restent séparables.</p><dl><div><dt>Source</dt><dd>Canonique</dd></div><div><dt>Structure</dt><dd>HTML initial</dd></div><div><dt>Dates</dt><dd>Historiques</dd></div></dl><button type="button" class="atelier-signal-copy" data-atelier-share data-url="<?php echo esc_url( $topic_url ); ?>" data-label="Copier le lien source"><svg aria-hidden="true" viewBox="0 0 24 24" focusable="false"><rect x="8" y="8" width="11" height="11" rx="1" fill="none" stroke="currentColor" stroke-width="1.6"/><path d="M5 16V5.5A1.5 1.5 0 0 1 6.5 4H17" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg><span data-share-label>Copier le lien source</span></button></section>'''
text, count = re.subn(r'<section class="atelier-reading-card".*?</section>', new_reading, text, count=1, flags=re.S)
assert count == 1, 'reading card not found'

new_related = '''<section class="atelier-related"><p class="atelier-kicker">À poursuivre</p><ol><?php foreach ( $related as $related_topic ) : $related_replies = function_exists( 'bbp_get_topic_reply_count' ) ? (int) bbp_get_topic_reply_count( $related_topic->ID ) : 0; ?><li><a href="<?php echo esc_url( get_permalink( $related_topic ) ); ?>"><span class="atelier-related__number"><?php echo esc_html( str_pad( (string) ( $related_topic->ID % 100 ), 2, '0', STR_PAD_LEFT ) ); ?></span><span class="atelier-related__copy"><strong><?php echo esc_html( get_the_title( $related_topic ) ); ?></strong><small><svg aria-hidden="true" viewBox="0 0 24 24" focusable="false"><path d="M5 6.5h14v10H9l-4 3v-3H5z" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/></svg><?php echo esc_html( $related_replies ); ?> réponse<?php echo 1 === $related_replies ? '' : 's'; ?></small></span><span class="atelier-related__arrow" aria-hidden="true">›</span></a></li><?php endforeach; ?></ol></section>'''
text, count = re.subn(r'<section class="atelier-related".*?</section>', new_related, text, count=1, flags=re.S)
