old_collection = '<a class="atelier-collection-card" href="<?php echo esc_url( function_exists( \'atelier_methods_url\' ) ? atelier_methods_url() : home_url( \'/methodes/\' ) ); ?>"><span>Collection</span><strong>Écrire pour être relu</strong><small>Explorer les repères →</small></a>'
new_collection = '<a class="atelier-collection-card" href="<?php echo esc_url( function_exists( \'atelier_methods_url\' ) ? atelier_methods_url() : home_url( \'/methodes/\' ) ); ?>" aria-label="Explorer la collection Écrire pour être relu"><span>Collection</span><strong>Écrire pour être relu</strong><small>Explorer les repères <span aria-hidden="true">↗</span></small></a>'
assert old_collection in text, 'collection card not found'
text = text.replace(old_collection, new_collection, 1)

old_h1 = '</h1>\n\t\t\t\t<div class="atelier-thread__facts">'
new_h1 = '</h1><p class="atelier-thread__deck">Nous cherchons une méthode simple pour que les conversations restent claires, citables et utiles — pour les membres comme pour les systèmes qui les découvrent.</p>\n\t\t\t\t<div class="atelier-thread__facts">'
